// Create the target file's parent directory before delegating to the base save, so a save
// into a not-yet-existing scenario folder succeeds.
// FUNCTION: IMPERIALISM 0x00479990
BOOL CAmbitDocument::OnSaveDocument(LPCTSTR lpszPathName) {
  CString dir(lpszPathName);
  int i = dir.GetLength() - 1;
  if (i > 0) {
    while (i > 0) {
      if (dir[i] == '/' || dir[i] == '\\') {
        break;
      }
      i--;
    }
    if (i > 0) {
      dir = dir.Left(i + 1);
      CreateDirectory(dir, NULL);
    }
  }
  return CDocument::OnSaveDocument(lpszPathName);
}
